      var r = moonDistKm(date || new Date());
      var f = 170800 / r;                 // disc radius as a fraction of the SVS frame side (~.42 apogee, ~.48 perigee)
      // scale keeps the on-screen disc constant; clip rides just inside the
      // limb so the frame's black border is trimmed the right amount every day
